WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT s.id, s.account_id, s.txn_type, s.merchant, s.is_flagged, s.is_new_burst, s.session_id, CASE WHEN txn_type RLIKE '^(FEE|CREDIT)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS txn_type_zone, (SELECT MIN(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS min_transaction_amount FROM sessionized s;
